<?php
/* SmartToolz — full repository dependency mind-map. The browser reads the public Git tree
   and source files, then draws actual file/folder relationships and inferred imports/includes. */
?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SmartToolz — Full File Mind Map</title>
<style>
:root{--bg:#030711;--panel:#08101d;--line:#263653;--text:#eaf1ff;--muted:#7785a5;--cyan:#29d9ff;--violet:#8a72ff;--green:#42f0a6;--red:#ff6378}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--text);font-family:Inter,system-ui,Arial,sans-serif}
body{background:radial-gradient(circle at 50% 45%,#0b1630 0,#030711 52%)}
.top{position:fixed;z-index:10;left:20px;right:20px;top:16px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.brand{pointer-events:auto}.eyebrow{font-size:9px;font-weight:900;letter-spacing:1.8px;color:#92a0c0}.eyebrow i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 14px var(--green);margin-right:7px;animation:pulse 1s infinite}.brand h1{margin:6px 0 3px;font-size:clamp(24px,3vw,40px);letter-spacing:-1.6px}.brand h1 span{color:var(--cyan)}.brand p{margin:0;color:var(--muted);font-size:10px}.hud{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;max-width:55%;pointer-events:auto}.pill{border:1px solid #ffffff18;background:#08101dcc;backdrop-filter:blur(10px);border-radius:10px;padding:9px 11px;color:#9eabc7;font:800 9px ui-monospace,monospace}.pill b{color:#fff}.controls{position:fixed;z-index:11;left:20px;bottom:18px;display:flex;gap:7px;align-items:center;pointer-events:auto}.btn{border:1px solid #ffffff18;background:#08101dcc;color:#dce6ff;border-radius:9px;padding:9px 11px;font-size:10px;font-weight:800;cursor:pointer}.btn:hover,.btn.active{border-color:#8a72ff99;background:#111a31}.search{width:220px;border:1px solid #ffffff18;background:#08101dcc;color:#fff;border-radius:9px;padding:9px 11px;outline:none;font-size:10px}.hint{position:fixed;right:20px;bottom:20px;z-index:10;color:#64728f;font:700 8px ui-monospace,monospace}
#stage{position:fixed;inset:0}canvas{display:block;width:100%;height:100%;cursor:grab}canvas.dragging{cursor:grabbing}.loading{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#030711ee}.loader{text-align:center}.loader .ring{width:54px;height:54px;border:2px solid #ffffff14;border-top-color:var(--cyan);border-right-color:var(--violet);border-radius:50%;animation:spin .8s linear infinite;margin:auto}.loader b{display:block;margin-top:14px;font-size:12px}.loader span{display:block;margin-top:5px;color:var(--muted);font-size:9px}
.panel{position:fixed;z-index:12;right:18px;top:90px;width:min(340px,calc(100vw - 36px));max-height:70vh;overflow:auto;border:1px solid #ffffff18;background:#07101eeF;backdrop-filter:blur(16px);border-radius:14px;padding:14px;display:none}.panel.show{display:block}.panel small{color:#71809f;font-size:8px;font-weight:900;letter-spacing:1px}.panel h2{margin:6px 0;font-size:14px;word-break:break-word}.panel code{display:block;color:#9deaff;font:9px ui-monospace,monospace;word-break:break-all;line-height:1.6}.panel .refs{margin-top:12px;color:#9aa7c2;font-size:9px;line-height:1.7}.panel a{color:var(--cyan);text-decoration:none}.legend{position:fixed;z-index:10;right:20px;bottom:55px;color:#65738e;font:700 8px ui-monospace,monospace;line-height:1.8;text-align:right}.legend span{margin-left:10px}.legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:4px;background:var(--cyan);box-shadow:0 0 8px currentColor}
@keyframes pulse{50%{opacity:.35;transform:scale(.75)}}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:700px){.top{left:12px;right:12px;top:11px}.hud{max-width:46%;gap:5px}.pill{padding:7px 8px}.brand p{display:none}.controls{left:12px;bottom:12px;right:12px}.search{flex:1;width:auto}.hint,.legend{display:none}.panel{top:80px;right:12px}}
</style>
</head>
<body>
<div id="loading" class="loading"><div class="loader"><div class="ring"></div><b>Building the repository mind map…</b><span id="loadText">Reading Git tree</span></div></div>
<header class="top"><div class="brand"><div class="eyebrow"><i></i>SMARTTOOLZ / REPOSITORY GRAPH</div><h1>Full File <span>Mind Map</span></h1><p>Actual repository files, folders and detected code references — rendered as a live dependency network.</p></div><div class="hud"><div class="pill">FILES <b id="fileCount">0</b></div><div class="pill">EDGES <b id="edgeCount">0</b></div><div class="pill">ACTIVE <b id="activeCount">0</b></div><div class="pill">STATUS <b id="status">LOADING</b></div></div></header>
<div id="stage"><canvas id="graph"></canvas></div>
<div id="panel" class="panel"><small>SELECTED FILE</small><h2 id="pTitle"></h2><code id="pPath"></code><div class="refs" id="pRefs"></div></div>
<div class="legend"><span><i style="color:var(--cyan)"></i>dependency / reference</span><span><i style="color:var(--violet)"></i>folder structure</span><span><i style="color:var(--green)"></i>active packet</span></div>
<div class="controls"><input id="search" class="search" placeholder="Find a file…" autocomplete="off"><button id="fit" class="btn">FIT</button><button id="pause" class="btn">PAUSE</button></div><div class="hint">DRAG = PAN • WHEEL = ZOOM • CLICK = INSPECT • R = RESET</div>
<script>
const REPO='codingbotlab/smarttoolz.in',BRANCH='main',RAW='https://raw.githubusercontent.com/'+REPO+'/'+BRANCH+'/';
const $=id=>document.getElementById(id), canvas=$('graph'),ctx=canvas.getContext('2d');
let W=0,H=0,dpr=1,nodes=[],edges=[],adj=new Map(),selected=null,hover=null,panX=0,panY=0,zoom=1,drag=false,lastX=0,lastY=0,paused=false,packets=[],sourceCache=new Map();
const textExt=/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|md|txt|xml|svg|yml|yaml|ini|conf|htaccess)$/i;
const skipPath=/(^|\/)(node_modules|vendor|\.git)(\/|$)/i;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function addEdge(a,b,type){if(!a||!b||a===b)return;const key=a.id+'>'+b.id;if(edges.some(e=>e.key===key))return;edges.push({a,b,type,key,energy:type==='dep'?1:.25});if(!adj.has(a.id))adj.set(a.id,[]);if(!adj.has(b.id))adj.set(b.id,[]);adj.get(a.id).push(b);adj.get(b.id).push(a)}
function pathBase(p){return p.replace(/^\.\//,'').replace(/\\/g,'/').replace(/[#?].*$/,'')}
function resolveRef(from,ref,all){ref=pathBase(ref);if(!ref||/^(https?:|data:|mailto:|javascript:|#|\/\/)/i.test(ref))return null;let clean=ref.replace(/^\//,'');let candidates=[];if(clean.startsWith('/'))candidates.push(clean.slice(1));else{const dir=from.split('/').slice(0,-1);const parts=(dir.concat(clean.split('/')));const out=[];for(const x of parts){if(x==='.'||!x)continue;if(x==='..')out.pop();else out.push(x)}candidates.push(out.join('/'))}for(const c of candidates){const variants=[c,c+'.php',c+'.js',c+'.css',c+'.json',c+'/index.php',c+'/index.html'];for(const v of variants){if(all.has(v))return all.get(v)}}return null}
function detectRefs(file,src,all){const refs=[];let m;const patterns=[/\b(?:require|require_once|include|include_once)\s*\(?\s*['"]([^'"]+)['"]/gi,/\b(?:import|export)\s+(?:[^'";]+?\s+from\s+)?['"]([^'"]+)['"]/gi,/\b(?:src|href)\s*=\s*['"]([^'"]+)['"]/gi,/\burl\(\s*['"]?([^'"')]+)['"]?\s*\)/gi];for(const re of patterns){while((m=re.exec(src))){const target=resolveRef(file.path,m[1],all);if(target&&target!==file)refs.push(target)}}return [...new Set(refs)]}
async function load(){try{$('loadText').textContent='Reading complete Git tree';const tree=await fetch('https://api.github.com/repos/'+REPO+'/git/trees/'+BRANCH+'?recursive=1').then(r=>{if(!r.ok)throw Error('GitHub tree '+r.status);return r.json()});const items=(tree.tree||[]).filter(x=>x.type==='blob'&&!skipPath.test(x.path));const all=new Map();items.forEach(x=>all.set(x.path,x));nodes=items.map((x,i)=>({id:x.path,path:x.path,name:x.path.split('/').pop(),x:0,y:0,vx:0,vy:0,r:x.path.includes('/')?3.2:5,type:x.path.includes('/')?'file':'root',refs:0}));const byPath=new Map(nodes.map(n=>[n.path,n]));
// Folder hierarchy: every file is connected to its immediate parent folder node; folders are real graph nodes too.
const folders=new Map();for(const it of items){const parts=it.path.split('/');for(let i=1;i<parts.length;i++){const f=parts.slice(0,i).join('/');if(!folders.has(f))folders.set(f,{id:'folder:'+f,path:f,name:parts[i-1]+'/',x:0,y:0,vx:0,vy:0,r:7,folder:true,refs:0})}}const folderNodes=[...folders.values()];nodes=[...folderNodes,...nodes];const lookup=new Map(nodes.map(n=>[n.id,n]));
for(const f of folderNodes){const parent=f.path.includes('/')?'folder:'+f.path.split('/').slice(0,-1).join('/'):'root';const p=parent==='root'?null:lookup.get(parent);if(p)addEdge(p,f,'tree')}
for(const n of nodes.filter(n=>!n.folder)){const parts=n.path.split('/');const parent=parts.length>1?lookup.get('folder:'+parts.slice(0,-1).join('/')):null;if(parent)addEdge(parent,n,'tree')}
$('fileCount').textContent=items.length+' + '+folderNodes.length+' dirs';
$('loadText').textContent='Reading source references';const sourceFiles=items.filter(x=>textExt.test(x.path)&&x.size<250000);let done=0;for(let i=0;i<sourceFiles.length;i+=10){const batch=sourceFiles.slice(i,i+10);await Promise.all(batch.map(async it=>{try{const s=await fetch(RAW+encodeURI(it.path),{cache:'no-store'}).then(r=>r.ok?r.text():'');sourceCache.set(it.path,s);done++;const n=byPath.get(it.path);detectRefs(n,s,byPath).forEach(t=>{addEdge(n,t,'dep');n.refs++;t.refs++})}catch(e){}}));$('loadText').textContent='Scanning references '+done+'/'+sourceFiles.length}
$('edgeCount').textContent=edges.length;$('activeCount').textContent='0';$('status').textContent='LIVE';$('loading').style.display='none';layout();requestAnimationFrame(loop)}catch(e){$('loadText').textContent='Could not read repository: '+e.message}}
function layout(){const cx=W/2,cy=H/2;nodes.forEach((n,i)=>{const a=i/nodes.length*Math.PI*2;const rr=n.folder?Math.min(W,H)*(.12+.15*(i%7)/7):Math.min(W,H)*(.25+.22*((i*17)%100)/100);n.x=cx+Math.cos(a)*rr;n.y=cy+Math.sin(a)*rr;n.vx=0;n.vy=0});for(let k=0;k<80;k++)simulate(.7)}
function simulate(dt){const cx=W/2,cy=H/2;for(const n of nodes){n.vx+=(cx-n.x)*.00035*dt;n.vy+=(cy-n.y)*.00035*dt}for(let i=0;i<nodes.length;i++){const a=nodes[i];for(let j=i+1;j<nodes.length;j++){const b=nodes[j];const dx=b.x-a.x,dy=b.y-a.y,d2=dx*dx+dy*dy+1;if(d2>180000)continue;const f=1500/d2;const d=Math.sqrt(d2);a.vx-=dx/d*f;a.vy-=dy/d*f;b.vx+=dx/d*f;b.vy+=dy/d*f}}for(const e of edges){const a=e.a,b=e.b,dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1;const target=e.type==='tree'?70:120;const f=(d-target)*.002;a.vx+=dx/d*f;b.vx-=dx/d*f;a.vy+=dy/d*f;b.vy-=dy/d*f}for(const n of nodes){n.vx*=.82;n.vy*=.82;n.x+=n.vx*dt;n.y+=n.vy*dt}}
function project(n){return{x:n.x*zoom+panX,y:n.y*zoom+panY}}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();for(const e of edges){const a=project(e.a),b=project(e.b);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=e.type==='dep'?'rgba(41,217,255,.25)':'rgba(138,114,255,.12)';ctx.lineWidth=e.type==='dep'?1.15:0.65;ctx.stroke();if(e.type==='dep'&&!paused){const t=(performance.now()/1800+hash(e.key))%1;const x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t;ctx.beginPath();ctx.arc(x,y,2.5,0,Math.PI*2);ctx.fillStyle='#42f0a6';ctx.shadowBlur=10;ctx.shadowColor='#42f0a6';ctx.fill();ctx.shadowBlur=0}}
for(const n of nodes){const p=project(n);let active=n===selected||n===hover||n.refs>0&&selected&&adj.get(selected.id)?.includes(n);const rr=(n.r+(active?2:0))*Math.max(.65,Math.min(1.6,zoom));ctx.beginPath();ctx.arc(p.x,p.y,rr,0,Math.PI*2);ctx.fillStyle=n.folder?'#8a72ff':(n===selected?'#fff':n===hover?'#29d9ff':'#17243d');ctx.shadowBlur=active?16:5;ctx.shadowColor=n.folder?'#8a72ff':'#29d9ff';ctx.fill();ctx.shadowBlur=0;if(active||zoom>.8){ctx.font=(active?'700 ':'500 ')+(n.folder?9:8)+'px ui-monospace,monospace';ctx.fillStyle=active?'#eaf1ff':'#6e7d9c';ctx.fillText(n.name,p.x+rr+4,p.y+3)}}ctx.restore()}
function hash(s){let h=0;for(let i=0;i<s.length;i++)h=((h<<5)-h+s.charCodeAt(i))|0;return (h>>>0)/4294967295}
function loop(){if(!paused){simulate(.18)}draw();requestAnimationFrame(loop)}
function hit(x,y){let best=null,bd=Infinity;for(const n of nodes){const p=project(n),d=Math.hypot(x-p.x,y-p.y);if(d<Math.max(12,n.r*3)&&d<bd){best=n;bd=d}}return best}
canvas.addEventListener('pointerdown',e=>{drag=true;canvas.classList.add('dragging');lastX=e.clientX;lastY=e.clientY});addEventListener('pointerup',()=>{drag=false;canvas.classList.remove('dragging')});addEventListener('pointermove',e=>{if(drag){panX+=e.clientX-lastX;panY+=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY}else hover=hit(e.clientX,e.clientY)});canvas.addEventListener('click',e=>{if(drag)return;const n=hit(e.clientX,e.clientY);selected=n;if(n){$('panel').classList.add('show');$('pTitle').textContent=n.folder?'📁 '+n.name:n.name;$('pPath').textContent=n.path;const linked=(adj.get(n.id)||[]).filter(x=>x!==n);$('pRefs').innerHTML='<b>'+linked.length+'</b> connected nodes<br>'+linked.slice(0,30).map(x=>'→ '+(x.folder?'📁 ':'')+x.path).join('<br>')+(linked.length>30?'<br>… '+(linked.length-30)+' more':'')}else $('panel').classList.remove('show')});canvas.addEventListener('wheel',e=>{e.preventDefault();const old=zoom;zoom=Math.max(.18,Math.min(4,zoom*(e.deltaY<0?1.1:.9)));const mx=e.clientX,my=e.clientY;panX=mx-(mx-panX)*(zoom/old);panY=my-(my-panY)*(zoom/old)},{passive:false});
$('fit').onclick=()=>{zoom=1;panX=0;panY=0;layout()};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'PLAY':'PAUSE';$('status').textContent=paused?'PAUSED':'LIVE'};addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'){$('fit').click()}if(e.key==='Escape'){$('panel').classList.remove('show')}});$('search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();selected=q?nodes.find(n=>n.path.toLowerCase().includes(q)):null;if(selected){const p=project(selected);panX+=W/2-p.x;panY+=H/2-p.y;$('panel').classList.add('show');$('pTitle').textContent=selected.name;$('pPath').textContent=selected.path;$('pRefs').textContent=(adj.get(selected.id)||[]).length+' connected nodes'}else $('panel').classList.remove('show')});
load();
</script></body></html>